        // Build a minimal ProductInfo in memory for initialize. Many fields are complex types; we supply simple valid defaults.
        C.ProductInfo memory info;

        info.name = "P";
        info.symbol = "P";

        // payoffDefinition: minimal valid PayoffDefinition (uses enums and data); we can pass zeros that are acceptable
        info.payoffDefinition = C.PayoffDefinition({payoffType: C.PayoffDefinitionLib.PayoffType(0), payoffDirection: C.PayoffDefinitionLib.PayoffDirection(0), data: bytes30(0)});

        // oracle: pass zero address — __UPayoffProvider__initialize will call _updateOracle which requires isContract(newOracle) true
        // So we need a dummy contract implementing IOracleProvider. Deploy a trivial oracle below.
        SimpleOracle oracle = new SimpleOracle();
        info.oracle = oracle;

        // Construct UFixed18 typed fields by scaling rawMaintenanceWholeUnits by 1e18 via inline encoding of uint256
        // We can't directly call UFixed18.wrap here; instead ProductInfo expects the UFixed18 type from the contract's ABI,
        // which is an alias for uint256 in calldata. So we pass scaled values as uint256.
        uint256 scaledMaintenance = rawMaintenanceWholeUnits * 1e18;

        info.maintenance = scaledMaintenance; // UFixed18 in ABI is uint256
        info.fundingFee = 0;
        info.makerFee = 0;
        info.takerFee = 0;
        info.positionFee = 0;
        info.makerLimit = type(uint256).max;

        // utilizationCurve: JumpRateUtilizationCurve struct fields are primitive numeric types in the ABI (int128/uint128 packed types
        // are passed as int256/uint256 in calldata). Provide zeros for rates and 1 for targetUtilization to be valid.
        C.JumpRateUtilizationCurve memory curve = C.JumpRateUtilizationCurve({minRate: 0, maxRate: 0, targetRate: 0, targetUtilization: 0});
        info.utilizationCurve = curve;

        // controller() must refer to msg.sender at initialize; C.__UControllerProvider__initialize expects msg.sender to be a contract that is a Controller.
        // The simplest approach is to deploy a MinimalController that satisfies the methods used during initialization: it must be a contract
        // (Address.isContract check) and later some calls in initialize path read controller in modifiers; however initialize only calls __UControllerProvider__initialize
        // which requires Address.isContract(address(controller_)) — so deploy a minimal controller and call initialize with its address as msg.sender.
        MinimalController controller = new MinimalController();

        // We must call initialize with msg.sender == controller (because __UControllerProvider__initialize expects IController(msg.sender) inside initialize in C)
        // So use vm.prank to make the call appear from the controller address.
        vm.prank(address(controller));
        c.initialize(info);

        // Now call maintenance(account). The contract's maintenance(address) returns the stored maintenance for the product instance.
        // We pick a fuzzed account address as well to ensure it's an arbitrary account; fuzzing suggestion requires at least one parameter,
        // which we already have. Use address(this) for a deterministic caller.

        // Observe returned maintenance via public getter. According to reference C, maintenance() should return the stored maintenance value
        // (scaledMaintenance). The mutant returns constant ONE (1e18) regardless of stored value, so when scaledMaintenance != 1e18 the mutant differs.

        uint256 returned = c.maintenance(address(this));

        // Assert that returned equals the stored scaledMaintenance value we initialized with.
        // This is the single assertion: the correct contract always returns the stored maintenance; the mutant will fail when rawMaintenanceWholeUnits != 1.
        assertTrue(returned == scaledMaintenance);
    }
}

