        // To call initialize we need to craft a ProductInfo. We will construct a bytes payload to call initialize
        // via low-level call so the fuzz tester can still observe maintenance() getter afterwards.

        // Prepare abi-encoded minimal ProductInfo matching the struct layout in C (field order matters).
        // We'll supply zero/empty values for complex fields; this should succeed for the reference contract when
        // msg.sender is treated as controller in __UControllerProvider__initialize which expects msg.sender to be
        // a contract satisfying IController; however __UControllerProvider__initialize checks Address.isContract(address(controller_))
        // and will revert if msg.sender (we pass as productInfo_.oracle via initialize) is not a contract. To avoid
        // the Address.isContract check, we must call initialize() with msg.sender equal to a contract address.

        // Deploy a tiny dummy controller contract to act as msg.sender for initialize. We'll deploy it and then
        // perform a call from that contract to c.initialize(...). The dummy controller will call c.initialize with
        // the ProductInfo we assemble.
        DummyController controller = new DummyController();

        // Construct ProductInfo in calldata for the controller to forward. We'll set most fields to zero/empty.
        // Layout in Solidity ABI for struct ProductInfo:
        // (string name, string symbol, PayoffDefinition payoffDefinition (3 fields), IOracleProvider oracle (address),
        // UFixed18 maintenance, UFixed18 fundingFee, UFixed18 makerFee, UFixed18 takerFee, UFixed18 positionFee,
        // UFixed18 makerLimit, JumpRateUtilizationCurve utilizationCurve (4 fields))
        // To avoid complexity we encode strings as empty and nested structs as zeros/addresses(0).

        bytes memory name = bytes("");
        bytes memory symbol = bytes("");
        // payoffDefinition: (uint8 payoffType, uint8 payoffDirection, bytes30 data) -> encode as zeros
        bytes32 payoff_data = bytes32(0);
        address oracleAddr = address(0);

