        uint256 maintenance = maintenanceRaw;
        uint256 fundingFee = 0;
        uint256 makerFee = 0;
        uint256 takerFee = 0;
        uint256 positionFee = 0;
        uint256 makerLimit = 0;

        // JumpRateUtilizationCurve fields: PackedFixed18 minRate; PackedFixed18 maxRate; PackedFixed18 targetRate; PackedUFixed18 targetUtilization;
        // we'll pass zeros
        int128 minRate = 0;
        int128 maxRate = 0;
        int128 targetRate = 0;
        uint128 targetUtilization = 0;

        // Encode the ProductInfo according to ABI
        bytes memory productInfo = abi.encode(
            name,
            symbol,
            // PayoffDefinition as tuple (uint8,uint8,bytes30) but safest to encode full 32-byte slots
            uint8(0), // payoffType
            uint8(0), // payoffDirection
            bytes30(0),
            oracleAddr,
            maintenance,
            fundingFee,
            makerFee,
            takerFee,
            positionFee,
            makerLimit,
            minRate,
            maxRate,
            targetRate,
            targetUtilization
        );

        // Now have the controller call initialize on c with productInfo as calldata; controller will call as a contract
        bool ok = controller.callInitialize(address(c), productInfo);

        // After attempted initialize, read maintenance via the public getter. The reference contract always returns
        // the stored maintenance; if initialize succeeded it stored our maintenance value; if initialize reverted,
        // maintenance() will still return the default stored value (likely zero). The mutant returns ONE regardless.

        // Try to call maintenance(account) for an arbitrary account (we fuzz none), use address(1)
        // Use try/catch to avoid reverts, but maintenance is view and shouldn't revert.
        bool successRef;
