        try c.maintenance(address(1)) returns (uint256 v) {
            successRef = true;
            refMaintenance = v;
        } catch {
            successRef = false;
            refMaintenance = 0;
        }

        // The universal property to assert: the reference contract's maintenance(...) equals the stored maintenance we attempted to set.
        // However we cannot directly read the private storage; but we know if initialize succeeded (ok==true) then refMaintenance must equal maintenance (our input).
        // If initialize failed, refMaintenance should be the default (likely zero). In either case, the mutant that always returns ONE will differ from refMaintenance
        // for at least some maintenanceRaw values (e.g., maintenanceRaw != 1e18). So we assert that refMaintenance != type(uint256).max (a sanity check)
