        // This must hold for all fuzz inputs on the reference; the mutant which always returns ONE will cause this assertion to fail for those inputs where expected != ONE.
        // We use assertTrue with the equality check.
        assertTrue(refMaintenance == expected);
    }
}

// Minimal helper controller that is a contract (so Address.isContract returns true) and forwards initialize call
contract DummyController {
    function callInitialize(address target, bytes memory productInfo) public returns (bool) {
        // build calldata for initialize(ProductInfo)
        // function selector
        bytes4 sig = bytes4(keccak256("initialize((string,string,(uint8,uint8,bytes30),address,uint256,uint256,uint256,uint256,uint256,uint256,(int128,int128,int128,uint128)))"));
        // However assembling the exact nested tuple selector is brittle; instead just call initialize with raw bytes assuming C has initialize(ProductInfo)
        // We can call via low-level call and forward productInfo as the single argument encoded as bytes for the struct.
        // The simplest robust approach: call target.initialize(productInfo) via abi.encodeWithSelector where selector is c.initialize.selector
        // But we don't have the ABI of C here; so call the fallback using delegatecall style: pack the selector for initialize(address) won't match.
        // To avoid encoding fragility we'll attempt to call any function with calldata that starts with the selector for initialize from the known signature in the source:
        bytes memory data = abi.encodeWithSelector(bytes4(keccak256("initialize((string,string,bytes30,address,uint256,uint256,uint256,uint256,uint256,uint256,int128,int128,int128,uint128))")), productInfo);

        // Try a generic low-level call: it's acceptable if it fails; we return whether it succeeded.
        (bool success, ) = target.call(abi.encodePacked(bytes4(keccak256("initialize((string,string,(uint8,uint8,bytes30),address,uint256,uint256,uint256,uint256,uint256,uint256,(int128,int128,int128,uint128)))")), productInfo));
        return success;
    }
}

