        // that implements the minimal functions used by initialize and by onlyProductOwner checks: controller() must return an IController address that
        // recognizes this product as its product and whose owner returns msg.sender. To avoid reconstructing full controller, instead we will impersonate
        // msg.sender as the controller by calling initialize where msg.sender is this test contract. initialize sets controller to msg.sender. So call initialize
        // with a ProductInfo built using ABI encoding via helper local struct type is not possible. However solidity allows constructing the concrete tuple
        // inline when calling external function: c.initialize{...}(productInfo) where productInfo is a tuple literal matching the types. We'll attempt that.

        // Construct minimal PayoffDefinition and JumpRateUtilizationCurve via inline zero literals. This compiles because the types are known.
        // Prepare payoffDefinition zero value
        // PayoffDefinition defined as struct PayoffDefinition { PayoffDefinitionLib.PayoffType payoffType; PayoffDefinitionLib.PayoffDirection payoffDirection; bytes30 data; }
        // We can pass (uint8(0), uint8(0), bytes30(0)) casted appropriately.

        // Construct JumpRateUtilizationCurve with zero fields: (int128,int128,int128,uint128) packed types — pass zeros.

        // Now call initialize as this test contract (msg.sender) so controller becomes this test contract and owner checks will later use this test contract.
        // Build the tuple inline:
        C.ProductInfo memory pi;
        // Unfortunately solidity doesn't allow constructing external struct types from test due to visibility; we circumvent by building via abi.encode and low-level call.
        // We'll instead perform a low-level call to initialize with ABI encoded ProductInfo where we set takerFee = scaled.

        // Types for encoding: (string,string,tuple,uint256,address,uint256,uint256,uint256,uint256,uint256,tuple)
        // But payoffDefinition tuple and utilization curve tuple shapes are complex. We'll encode zeros for them by composing their ABI type string.

        bytes memory encoded = abi.encode(
            // name
            "",
            // symbol
            "",
            // payoffDefinition: (uint8,uint8,bytes30)
            uint8(0),
            uint8(0),
            bytes30(0),
            // oracle
            address(0),
            // maintenance
            uint256(0),
            // fundingFee
            uint256(0),
            // makerFee
            uint256(0),
            // takerFee -> set
            uint256(takerFee),
            // positionFee
            uint256(0),
            // makerLimit
            uint256(0),
            // utilizationCurve: (int128,int128,int128,uint128)
            int128(0),
            int128(0),
            int128(0),
            uint128(0)
        );

        // perform low-level call to initialize with constructed calldata
        (bool okInit, ) = address(c).call(abi.encodePacked(bytes4(keccak256("initialize((string,string,(uint8,uint8,bytes30),address,uint256,uint256,uint256,uint256,uint256,uint256,(int128,int128,int128,uint128)))")), encoded));
        // initialization may succeed or revert depending on packing; assume it succeeded for the purpose of exercising takerFee. If it failed, the stored takerFee remains zero
        // but the mutant also returns zero — that does not help. To ensure we get a non-zero stored takerFee in the reference, require okInit true.
        vm.assume(okInit == true);

        // Now call updateTakerFee as product owner (this test contract is owner since initialize set controller to this contract)
        // updateTakerFee signature: updateTakerFee(UFixed18)
        // Prepare call data
        (bool okUpdate, ) = address(c).call(abi.encodeWithSignature("updateTakerFee(uint256)", takerFee));
        // updateTakerFee is guarded by settleProduct which calls settle(); settle may revert if oracle or other components not set; to avoid revert we allow either path.
        vm.assume(okUpdate == true);

        // Single observable assertion: the public getter takerFee() must return the value we set (scaled) in the correct contract.
        // We retrieve via low-level staticcall to avoid revert bubbling
        (bool okGet, bytes memory ret) = address(c).call(abi.encodeWithSignature("takerFee()"));
        // If call succeeded, decode result
        uint256 observed = 0;
        if (okGet) {
            observed = abi.decode(ret, (uint256));
        }

        // Assert that observed equals the scaled value we set. In the reference this holds for all fuzz inputs (given the assumptions above),
        // while the mutant returns zero and this assertion will fail for inputs where scaled != 0.
        assertTrue(observed == takerFee);
    }
}

